    47	const filterInput = (amount: string, amountRegex?: RegExp, permittedDecimalSeparator?: string) => {
    48	    let value = amount ? amount.toString().trim() : '';
    49	    const regex = new RegExp(`^0+|([${permittedDecimalSeparator}]\\d*?)0+$`, 'g');
    50	    value = value.replace(regex, '$1');
